'use strict';

const kinds = new Set(['lab', 'kitchen', 'garden', 'studio']);
const nonEmpty = value => typeof value === 'string' && value.trim().length > 0;
const hasExactKeys = (value, expected) => {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return false;
  const keys = Object.keys(value);
  return keys.length === expected.length && expected.every(key => Object.prototype.hasOwnProperty.call(value, key));
};

function createWorkshopRegistry(initialHosts = []) {
  if (!Array.isArray(initialHosts)) throw new TypeError('initialHosts must be an array');

  const hosts = new Map();
  for (const host of initialHosts) {
    if (!hasExactKeys(host, ['id', 'name']) || !nonEmpty(host.id) || !nonEmpty(host.name)) {
      throw new TypeError('invalid host');
    }
    if (hosts.has(host.id)) throw new RangeError('duplicate host');
    hosts.set(host.id, { id: host.id, name: host.name });
  }

  const workshops = [];
  const names = new Set();
  const copy = item => ({
    name: item.name,
    kind: item.kind,
    address: item.address,
    host: { id: item.host.id, name: item.host.name }
  });

  function register(input) {
    if (!hasExactKeys(input, ['name', 'kind', 'address', 'host']) ||
        !nonEmpty(input.name) || !kinds.has(input.kind) || !nonEmpty(input.address)) {
      throw new TypeError('invalid workshop');
    }

    const key = input.name.trim().toLowerCase();
    if (names.has(key)) throw new RangeError('duplicate workshop');

    let resolvedHost;
    let pendingHost = null;

    if (hasExactKeys(input.host, ['id'])) {
      if (!nonEmpty(input.host.id) || !hosts.has(input.host.id)) {
        throw new TypeError('invalid host selection');
      }
      resolvedHost = hosts.get(input.host.id);
    } else if (hasExactKeys(input.host, ['newHost'])) {
      const candidate = input.host.newHost;
      if (!hasExactKeys(candidate, ['id', 'name']) || !nonEmpty(candidate.id) || !nonEmpty(candidate.name)) {
        throw new TypeError('invalid new host');
      }
      if (hosts.has(candidate.id)) throw new RangeError('duplicate host');
      pendingHost = { id: candidate.id, name: candidate.name };
      resolvedHost = pendingHost;
    } else {
      throw new TypeError('invalid host selection');
    }

    const workshop = {
      name: input.name,
      kind: input.kind,
      address: input.address,
      host: { id: resolvedHost.id, name: resolvedHost.name }
    };

    if (pendingHost) hosts.set(pendingHost.id, { ...pendingHost });
    names.add(key);
    workshops.push(workshop);
    return copy(workshop);
  }

  return {
    register,
    list() {
      return workshops.map(copy);
    }
  };
}

module.exports = { createWorkshopRegistry };
